






USE EcoRitos;
GO



IF COL_LENGTH('Reto', 'Subcategoria') IS NULL ALTER TABLE Reto ADD Subcategoria NVARCHAR(200) NULL;
IF COL_LENGTH('Reto', 'Tipo') IS NULL ALTER TABLE Reto ADD Tipo NVARCHAR(50) NULL;
IF COL_LENGTH('Reto', 'TiempoMin') IS NULL ALTER TABLE Reto ADD TiempoMin INT NULL;
IF COL_LENGTH('Reto', 'Materiales') IS NULL ALTER TABLE Reto ADD Materiales NVARCHAR(MAX) NULL;
IF COL_LENGTH('Reto', 'CantidadObjetivo') IS NULL ALTER TABLE Reto ADD CantidadObjetivo INT NULL;
IF COL_LENGTH('Reto', 'Consejos') IS NULL ALTER TABLE Reto ADD Consejos NVARCHAR(MAX) NULL;
IF COL_LENGTH('Reto', 'Advertencias') IS NULL ALTER TABLE Reto ADD Advertencias NVARCHAR(MAX) NULL;
IF COL_LENGTH('Reto', 'Requisitos') IS NULL ALTER TABLE Reto ADD Requisitos NVARCHAR(MAX) NULL;
IF COL_LENGTH('Reto', 'Evidencia') IS NULL ALTER TABLE Reto ADD Evidencia NVARCHAR(50) NULL;
IF COL_LENGTH('Reto', 'Etiquetas') IS NULL ALTER TABLE Reto ADD Etiquetas NVARCHAR(MAX) NULL;
IF COL_LENGTH('Reto', 'Destacado') IS NULL ALTER TABLE Reto ADD Destacado BIT NOT NULL DEFAULT 0;
IF COL_LENGTH('Reto', 'EsDiario') IS NULL ALTER TABLE Reto ADD EsDiario BIT NOT NULL DEFAULT 0;
IF COL_LENGTH('Reto', 'EsSemanal') IS NULL ALTER TABLE Reto ADD EsSemanal BIT NOT NULL DEFAULT 0;
IF COL_LENGTH('Reto', 'EsEspecial') IS NULL ALTER TABLE Reto ADD EsEspecial BIT NOT NULL DEFAULT 0;
GO

